// Dashboard page - the main page after login
// Shows: summary cards (income/expense/balance), add transaction form, transaction list

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import TransactionForm from '../components/TransactionForm';
import TransactionList from '../components/TransactionList';
import Navbar from '../components/Navbar';
import './Dashboard.css';

function Dashboard() {
  const [transactions, setTransactions] = useState([]);
  const navigate = useNavigate();

  const token = localStorage.getItem('token');

  // Fetch all transactions when the page loads
  useEffect(() => {
    fetchTransactions();
  }, []);

  const fetchTransactions = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/transactions', {
        headers: { Authorization: token }
      });
      setTransactions(response.data);
    } catch (error) {
      console.log('Error fetching transactions:', error.message);
    }
  };

  // Called after adding a new transaction to refresh the list
  const handleTransactionAdded = () => {
    fetchTransactions();
  };

  // Delete a transaction
  const handleDelete = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/transactions/${id}`, {
        headers: { Authorization: token }
      });
      // Remove it from state without re-fetching
      setTransactions(transactions.filter(t => t.id !== id));
    } catch (error) {
      console.log('Error deleting transaction:', error.message);
    }
  };

  // Calculate totals
  const totalIncome = transactions
    .filter(t => t.type === 'income')
    .reduce((sum, t) => sum + t.amount, 0);

  const totalExpense = transactions
    .filter(t => t.type === 'expense')
    .reduce((sum, t) => sum + t.amount, 0);

  const balance = totalIncome - totalExpense;

  return (
    <div>
      <Navbar />
      <div className="dashboard-container">

        {/* Summary Cards */}
        <div className="summary-cards">
          <div className="card income-card">
            <h3>Total Income</h3>
            <p>₹ {totalIncome.toFixed(2)}</p>
          </div>
          <div className="card expense-card">
            <h3>Total Expense</h3>
            <p>₹ {totalExpense.toFixed(2)}</p>
          </div>
          <div className="card balance-card">
            <h3>Balance</h3>
            <p>₹ {balance.toFixed(2)}</p>
          </div>
        </div>

        {/* Add Transaction Form */}
        <TransactionForm onTransactionAdded={handleTransactionAdded} />

        {/* Transaction List */}
        <TransactionList transactions={transactions} onDelete={handleDelete} />

      </div>
    </div>
  );
}

export default Dashboard;
